+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+import org.junit.jupiter.api.AfterAll;
+import org.junit.jupiter.api.BeforeAll;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+
+import com.microsoft.playwright.Browser;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.Playwright;
+import com.microsoft.playwright.options.AriaRole;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest {
+
+    private static Playwright playwright;
+    private static Browser browser;
+
+    @LocalServerPort
+    private int port;
+
+    @BeforeAll
+    static void start() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch();
+    }
+
+    @AfterAll
+    static void stop() {
+        browser.close();
+        playwright.close();
+    }
+
+    @Test
+    void sendAndLeave() {
+        Page page = browser.newPage();
+        page.navigate("http://localhost:" + port + "/contact");
+        assertThat(page.locator("h1")).hasText("Contact");
+
+        Page.GetByRoleOptions send = new Page.GetByRoleOptions().setName("Send");
+        page.getByRole(AriaRole.BUTTON, send).click();
+        assertThat(page.locator("vaadin-text-field").first()).hasAttribute("invalid", "");
+        assertThat(page.getByText("Give an e-mail address or a phone number")).isVisible();
+
+        page.getByLabel("Name").fill("Dora");
+        page.getByLabel("Email").fill("bad");
+        page.getByLabel("Message").fill("Hi there");
+        page.getByRole(AriaRole.BUTTON, send).click();
+        assertThat(page.getByText("Enter a valid e-mail address")).isVisible();
+
+        page.getByLabel("Email").fill("dora@example.com");
+        page.getByLabel("Email").press("Enter");
+        assertThat(page.locator("vaadin-notification-card")).containsText("Message sent");
+        assertThat(page.locator("vaadin-grid-cell-content").getByText("Hi there")).isVisible();
+        assertThat(page.getByRole(AriaRole.BUTTON, send)).isDisabled();
+        page.getByLabel("Phone").fill("1");
+        assertThat(page.getByRole(AriaRole.BUTTON, send)).isEnabled();
+
+        page.getByText("About").click();
+        assertThat(page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing"))).isVisible();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(page.getByLabel("Phone")).hasValue("1");
+
+        page.getByText("About").click();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+        assertThat(page.locator("h1")).hasText("About");
+
+        page.getByText("Contact").click();
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(page.locator("vaadin-grid-cell-content").getByText("Hi there")).isVisible();
+        assertThat(page.getByRole(AriaRole.BUTTON, send)).isEnabled();
+
+        // Back button with a dirty form asks too, and keeps working afterwards
+        page.getByLabel("Name").fill("Eve");
+        page.goBack();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(page.getByLabel("Name")).hasValue("Eve");
+        page.getByText("About").click();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+        assertThat(page.locator("h1")).hasText("About");
+
+        // Empty form: no dialog
+        page.getByText("Contact").click();
+        page.getByText("About").click();
+        assertThat(page.locator("h1")).hasText("About");
+        assertThat(page.locator("vaadin-dialog")).hasCount(0);
+        page.close();
+    }
+}
