+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name;
+    private EmailField email;
+    private TextField phone;
+    private TextArea message;
+    private Button send;
+
+    @BeforeEach
+    void open() {
+        navigate(ContactView.class);
+        name = $(TextField.class).withLabel("Name").single();
+        email = $(EmailField.class).withLabel("Email").single();
+        phone = $(TextField.class).withLabel("Phone").single();
+        message = $(TextArea.class).withLabel("Message").single();
+        send = $(Button.class).withText("Send").single();
+    }
+
+    @Test
+    void initialState() {
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertTrue(name.isEmpty() && email.isEmpty() && phone.isEmpty() && message.isEmpty());
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void emptyFormShowsAllErrors() {
+        test(send).click();
+        assertError(name, "Name is required");
+        assertError(email, "Give an e-mail address or a phone number");
+        assertError(message, "Message is required");
+        assertFalse($(Notification.class).exists());
+    }
+
+    @Test
+    void invalidEmailAndLongMessage() {
+        int rows = test($(Grid.class).single()).size();
+        test(name).setValue("Ann");
+        test(email).setValue("not-an-email");
+        test(message).setValue("x".repeat(501));
+        test(send).click();
+        assertFalse(name.isInvalid());
+        assertError(email, "Enter a valid e-mail address");
+        assertError(message, "Message must be at most 500 characters");
+        assertEquals("not-an-email", email.getValue());
+        assertEquals(rows, test($(Grid.class).single()).size());
+        assertFalse($(Notification.class).exists());
+    }
+
+    @Test
+    @SuppressWarnings("unchecked")
+    void sendWithPhoneOnlyThenEnter() {
+        test(name).setValue("Bob");
+        test(phone).setValue("12345");
+        test(message).setValue("Hello");
+        test(send).click();
+
+        assertTrue($(Notification.class).last().getElement().getProperty("text", "").contains("Message sent")
+                || test($(Notification.class).last()).getText().contains("Message sent"));
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        assertEquals("Bob", test(grid).getRow(0).name());
+        assertEquals("Hello", test(grid).getRow(0).message());
+        assertTrue(name.isEmpty() && email.isEmpty() && phone.isEmpty() && message.isEmpty());
+        assertFalse(send.isEnabled());
+
+        test(name).setValue("Carl");
+        assertTrue(send.isEnabled());
+        test(email).setValue("carl@example.com");
+        test(message).setValue("Via enter");
+        fireShortcut(Key.ENTER);
+        assertEquals("Carl", test(grid).getRow(0).name());
+        assertFalse(send.isEnabled());
+
+        // The list survives leaving and returning
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+        Grid<ContactMessage> again = $(Grid.class).single();
+        assertEquals("Carl", test(again).getRow(0).name());
+        assertEquals("Bob", test(again).getRow(1).name());
+    }
+
+    @Test
+    void emptyFormLeavesWithoutDialog() {
+        test($(RouterLink.class).withText("About").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertFalse($(Dialog.class).exists());
+    }
+
+    @Test
+    void dirtyFormAsksBeforeLeaving() {
+        test(message).setValue("Draft");
+        test($(RouterLink.class).withText("About").single()).click();
+        assertInstanceOf(ContactView.class, getCurrentView());
+        Dialog dialog = $(Dialog.class).single();
+        test($(Button.class, dialog).withText("Keep editing").single()).click();
+        assertFalse(dialog.isOpened());
+        assertEquals("Draft", message.getValue());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        com.vaadin.flow.component.UI.getCurrent().navigate(AboutView.class);
+        assertInstanceOf(ContactView.class, getCurrentView());
+        Dialog second = $(Dialog.class).single();
+        test($(Button.class, second).withText("Discard").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    private static void assertError(com.vaadin.flow.component.HasValidation field, String error) {
+        assertTrue(field.isInvalid());
+        assertEquals(error, field.getErrorMessage());
+    }
+}
